48	        checkPresent("telephone", request.getTelephone(), errors);
49	        // A supplied registrationDate may not be in the future: reject a date later than the
50	        // server's current date. Absent is accepted (it defaults to today when the owner is built).
51	        LocalDate registrationDate = request.getRegistrationDate();
52	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
53	            errors.add("registrationDate");
54	        }
55	        if (!errors.isEmpty()) {
56	            throw new OwnerFieldsInvalidException(errors);
57	        }
58	        // Store and return the normalized address; later steps read it back via @Val.
59	        request.setAddress(address);
60	        String telephone = E164Telephone.normalize(request.getTelephone());
61	        if (telephone == null) {
62	            throw new OwnerFieldsInvalidException(List.of("telephone"));
63	        }
64	        request.setTelephone(telephone);
